return [{ json: {
  chatId:       $json.chatId,
  firstName:    $json.firstName,
  fileId:       $json.fileId,
  caption:      $json.caption,
  telegramToken: 'whatsapp_no_token_needed'
} }];

const callbackData = $json.callbackData;
const match = callbackData.match(/^CANCEL_(.+)_(\d+)$/);
if (!match) throw new Error('Format callback invalide: ' + callbackData);
const eventId = match[1];
const chatId = match[2];
return [{ json: {
  eventId,
  chatId,
  callbackQueryId: $json.callbackQueryId,
  firstName: $json.firstName
}}];

const response = $input.first().json;
const items = response.items || [];
const prep = $('Préparer Vérif Immédiate').first().json;
const bookingStart = new Date(prep.startDate).getTime();
const bookingEnd = new Date(prep.endDate).getTime();

const hasConflict = items.some(ev => {
  if (!ev.id) return false;
  if (!ev.start?.dateTime) return false;
  const evStart = new Date(ev.start.dateTime).getTime();
  const evEnd = new Date(ev.end.dateTime).getTime();
  return evStart < bookingEnd && evEnd > bookingStart;
});

return [{ json: { chatId: prep.chatId, startDate: prep.startDate, endDate: prep.endDate, booking: prep.booking, hasConflict } }];

const chatId = $input.first().json.chatId;
const staticData = $getWorkflowStaticData('global');
const booking = staticData['booking_' + chatId];
if (!booking) throw new Error('Booking introuvable pour ' + chatId);

const durations = { eco: 45, standard: 75, premium: 120 };
const duration = durations[booking.formule] || 60;

const [h, m] = booking.heure.split(':').map(Number);
const endMinutes = h * 60 + m + duration;
const endH = String(Math.floor(endMinutes / 60)).padStart(2, '0');
const endM = String(endMinutes % 60).padStart(2, '0');

function frenchOffset(dateStr) {
  const year = parseInt(dateStr.slice(0, 4));
  const mar = new Date(Date.UTC(year, 2, 31));
  mar.setUTCDate(31 - mar.getUTCDay());
  const oct = new Date(Date.UTC(year, 9, 31));
  oct.setUTCDate(31 - oct.getUTCDay());
  const d = new Date(dateStr + 'T00:00:00Z');
  return (d >= mar && d < oct) ? '+02:00' : '+01:00';
}

const offset = frenchOffset(booking.date);
const startDate = booking.date + 'T' + booking.heure + ':00' + offset;
const endDate = booking.date + 'T' + endH + ':' + endM + ':00' + offset;

return [{ json: { chatId, startDate, endDate, booking } }];

const data = $input.first().json;
const chatId = data.chatId;
const booking = data.booking;
const bookedDate = booking.date;
const bookedTime = booking.heure;

const dayNames = ['Dimanche', 'Lundi', 'Mardi', 'Mercredi', 'Jeudi', 'Vendredi', 'Samedi'];
const monthNames = ['janvier', 'f\u00e9vrier', 'mars', 'avril', 'mai', 'juin', 'juillet', 'ao\u00fbt', 'septembre', 'octobre', 'novembre', 'd\u00e9cembre'];

// R\u00e9cup\u00e9rer les cr\u00e9neaux pris depuis le cache static
const staticData = $getWorkflowStaticData('global');
const bookedSlots = staticData['bookedSlotsCache'] || [];

const durations = { eco: 45, standard: 75, premium: 120 };
const duration = durations[booking.formule] || 60;
const [bookedH, bookedM] = bookedTime.split(':').map(Number);

function isSlotTaken(date, startH, startM, durationMin) {
  const slotStart = startH * 60 + startM;
  const slotEnd = slotStart + durationMin;
  return bookedSlots.some(bs => {
    if (bs.date !== date) return false;
    const bsStart = bs.startH * 60 + bs.startM;
    const bsEnd = bs.endH * 60 + bs.endM;
    return slotStart < bsEnd && slotEnd > bsStart;
  });
}

// Trouver les 3 prochains cr\u00e9neaux libres (jusqu'\u00e0 10 jours)
const alternatives = [];
const baseDate = new Date(bookedDate + 'T12:00:00Z');
let offset = 1;
while (alternatives.length < 3 && offset <= 10) {
  const next = new Date(baseDate);
  next.setUTCDate(baseDate.getUTCDate() + offset);
  const nextDate = `${next.getUTCFullYear()}-${String(next.getUTCMonth()+1).padStart(2,'0')}-${String(next.getUTCDate()).padStart(2,'0')}`;
  if (!isSlotTaken(nextDate, bookedH, bookedM, duration)) {
    const dayName = dayNames[next.getUTCDay()];
    const day = String(next.getUTCDate()).padStart(2, '0');
    const month = next.getUTCMonth();
    const year = next.getUTCFullYear();
    alternatives.push(`\u2022 ${dayName} ${day} ${monthNames[month]} \u00e0 ${bookedTime}`);
  }
  offset++;
}

const altText = alternatives.length > 0
  ? alternatives.join('\n')
  : '\u2022 Contactez-nous pour trouver un cr\u00e9neau disponible';

const message = `\u274c Ce cr\u00e9neau (${bookedDate} \u00e0 ${bookedTime}) est d\u00e9j\u00e0 r\u00e9serv\u00e9 !\n\nVoici des alternatives disponibles :\n${altText}\n\nR\u00e9pondez avec votre choix ou proposez une autre date/heure \ud83d\ude4f`;

// On sauvegarde les infos actuelles dans le cache global avant de sortir
// pour que l'IA puisse les retrouver au prochain message du client
staticData['pending_booking_' + chatId] = booking;

return [{ 
  json: { 
    chatId, 
    message, 
    booking,
    // On ajoute un rappel pour le debug ou le prompt
    context_reminder: `Client: ${booking.client}, Véhicule: ${booking.vehicule}, Formule: ${booking.formule}, Adresse: ${booking.adresse}`
  } 
}];

const response = $input.first().json;
const items = response.items || [];
const booking = $('Récupérer Booking + Préparer Cal').first().json;
const bookingStart = new Date(booking.startDate).getTime();
const bookingEnd = new Date(booking.endDate).getTime();

// Ignorer les événements all-day (start.date sans heure) - anniversaires, rappels, etc.
// Seuls les événements avec start.dateTime peuvent créer un conflit
const hasConflict = items.some(ev => {
  if (!ev.id) return false;
  if (!ev.start?.dateTime) return false; // skip all-day events
  const evStart = new Date(ev.start.dateTime).getTime();
  const evEnd = new Date(ev.end.dateTime).getTime();
  return evStart < bookingEnd && evEnd > bookingStart;
});

return [{ json: { ...booking, hasConflict } }];

const calResponse = $input.first().json;
const source = $('Extraire Données Message').first().json;
const events = calResponse.items || [];
const staticData = $getWorkflowStaticData('global');

// --- RÉCUPÉRATION DU BOOKING EN ATTENTE ---
const pendingBooking = staticData['pending_booking_' + source.chatId];
let bookingContext = "";

if (pendingBooking) {
  bookingContext = `\n[INFOS_DÉJÀ_COLLECTÉES]\n` +
    `- Client: ${pendingBooking.client}\n` +
    `- Véhicule: ${pendingBooking.vehicule}\n` +
    `- Formule: ${pendingBooking.formule}\n` +
    `- Adresse: ${pendingBooking.adresse}\n` +
    `- Téléphone: ${pendingBooking.telephone}\n` +
    `L'utilisateur a déjà fourni ces informations. NE LES REDEMANDE PAS. Il doit juste valider une nouvelle date.\n`;
}


// Lire les formules depuis Google Sheets
let formulesContext = '';
try {
  const formulesRows = $('Lire Formules').all();
  if (formulesRows && formulesRows.length > 0) {
    const firstRow = formulesRows[0].json;
    const headers = Object.keys(firstRow);
    formulesContext += headers.join(' | ') + '\n';
    formulesContext += headers.map(() => '---').join(' | ') + '\n';
    formulesRows.forEach(item => {
      const row = item.json;
      formulesContext += headers.map(h => String(row[h] !== undefined ? row[h] : '')).join(' | ') + '\n';
    });
  }
} catch(e) {
  formulesContext = '';
}

const dayNames = ['Dimanche','Lundi','Mardi','Mercredi','Jeudi','Vendredi','Samedi'];

function toParisLocal(isoStr) {
  const d = new Date(isoStr);
  const year = d.getUTCFullYear();
  const mar = new Date(Date.UTC(year, 2, 31));
  mar.setUTCDate(31 - mar.getUTCDay());
  const oct = new Date(Date.UTC(year, 9, 31));
  oct.setUTCDate(31 - oct.getUTCDay());
  const offsetMs = (d >= mar && d < oct) ? 2 * 3600000 : 3600000;
  return new Date(d.getTime() + offsetMs);
}

const timedEvents = events.filter(ev => ev.start && ev.start.dateTime);
const bookedSlotsData = timedEvents.map(ev => {
  const start = toParisLocal(ev.start.dateTime);
  const end = toParisLocal(ev.end.dateTime);
  return {
    date: `${start.getUTCFullYear()}-${String(start.getUTCMonth()+1).padStart(2,'0')}-${String(start.getUTCDate()).padStart(2,'0')}`,
    startH: start.getUTCHours(), startM: start.getUTCMinutes(),
    endH: end.getUTCHours(), endM: end.getUTCMinutes()
  };
});

staticData['bookedSlotsCache'] = bookedSlotsData;

let calendarLines = [];
const now = new Date();
for (let i = 0; i <= 14; i++) {
  const d = new Date(now);
  d.setDate(now.getDate() + i);
  const dayName = dayNames[d.getDay()];
  const day = String(d.getDate()).padStart(2, '0');
  const month = String(d.getMonth() + 1).padStart(2, '0');
  const year = d.getFullYear();
  const iso = `${year}-${month}-${day}`;
  const label = i === 0 ? " (aujourd'hui)" : i === 1 ? " (demain)" : "";
  calendarLines.push(`${dayName} ${day}/${month}/${year} -> ${iso}${label}`);
}

// Créneaux urgence
const URGENCE_SEUIL_JOURS = 6;
let urgencyLines = [];
for (let i = 0; i <= URGENCE_SEUIL_JOURS; i++) {
  const d = new Date(now);
  d.setDate(now.getDate() + i);
  if (d.getDay() === 6) {
    const day = String(d.getDate()).padStart(2, '0');
    const month = String(d.getMonth() + 1).padStart(2, '0');
    const year = d.getFullYear();
    const iso = `${year}-${month}-${day}`;
    urgencyLines.push(`${iso} 14:00 | URGENCE +50% | Créneau très demandé, délai < 48h`);
  }
}
const urgencyContext = urgencyLines.join('\n');

// État véhicule analysé par photo (si disponible)
const storedEtat = staticData['etat_vehicule_' + source.chatId];
let etatPhotoContext = '';
if (storedEtat) {
  etatPhotoContext = `${storedEtat.etat}${storedEtat.justification ? ' — ' + storedEtat.justification : ''}`;
}

return [{ json: { ...source, calendarContext: calendarLines.join('\n'), formulesContext, urgencyContext, etatPhotoContext,bookingContext } }];

