const devisNum = $('Détecter et Stocker RDV').first().json.devisNum || '';
const staticData = $getWorkflowStaticData('global');

const calItems = $input.first().json.items || [];
const event = calItems.find(e => (e.summary || '').includes(devisNum));
const eventId = event?.id || staticData['cal_event_' + chatId];

if (!eventId) throw new Error('Aucun événement calendrier trouvé pour ' + devisNum);

delete staticData['cal_event_' + chatId];
return [{ json: { chatId, eventId } }];

