const chatId = $input.first().json.chatId;
const staticData = $getWorkflowStaticData('global');
const booking = staticData['booking_' + chatId];
if (!booking) throw new Error('Booking introuvable dans staticData pour ' + chatId);

const dayNames   = ['Dimanche','Lundi','Mardi','Mercredi','Jeudi','Vendredi','Samedi'];
const monthNames = ['janvier','février','mars','avril','mai','juin','juillet','août','septembre','octobre','novembre','décembre'];
const d       = new Date(booking.date + 'T00:00:00');
const dateStr = dayNames[d.getDay()] + ' ' + d.getDate() + ' ' + monthNames[d.getMonth()] + ' ' + d.getFullYear();

const vehicles = { citadine:'Citadine 🚗', berline:'Berline 🚙', suv:'SUV/4x4 🚕', utilitaire:'Utilitaire 🚐' };
const formulas = { express:'Express 🚿', standard:'Standard ✨', premium:'Premium 💎', duo:'Duo 🔄', gold:'Gold 🏆' };

const recap =
  '🧾 *Récapitulatif de votre demande*\n' +
  '━━━━━━━━━━━━━━━\n' +
  '👤 *Client :* ' + (booking.client || 'Client') + '\n' +
  '📞 *Tél :* ' + (booking.telephone || 'Non renseigné') + '\n' +
  (vehicles[booking.vehicule] || booking.vehicule) + '\n' +
  (formulas[booking.formule] || booking.formule) + '\n' +
  '📍 *Adresse :* ' + booking.adresse + '\n' +
  '📅 *Date :* ' + dateStr + ' à ' + booking.heure + '\n' +
  '━━━━━━━━━━━━━━━';

// Marquer que ce client attend une confirmation 1/2
staticData['awaitingConfirmation_' + chatId] = true;

return [{ json: { chatId, recap, booking } }];

const rawText = ($('Extraire Données Message').first().json.text || '').trim();
const chatId = $('Extraire Données Message').first().json.chatId;
const staticData = $getWorkflowStaticData('global');

// ── ANNULATION DEVIS PAR NUMÉRO ────────────────���────────────────────────������������������������������───────
const cancelMatch = rawText.match(/annule[^a-zA-Z]*(le\s+)?devis\s+(KK-\d{4}-\d{4})/i);
if (cancelMatch) {
  const devisNum = cancelMatch[2].toUpperCase();
  ['booking_','pending_booking_','photoAsked_','etatAsked_','pendingPhotos_','awaitingConfirmation_','awaitingDevisConfirmation_'].forEach(k => delete staticData[k + chatId]);
  const hasCalEvent = !!staticData['cal_event_' + chatId];
  if (hasCalEvent) {
    return [{ json: { chatId, devisNum, output: 'Votre devis ' + devisNum + ' et votre rendez-vous ont bien été annulés. 😊 Revenez quand vous voulez !', isBookingReady: false, directRecap: false, isCancelRequest: true, booking: null } }];
  }
  return [{ json: { chatId, devisNum, output: 'Votre devis ' + devisNum + ' a bien été annulé. 😊 Revenez quand vous voulez !', isBookingReady: false, directRecap: false, isCancelRequest: false, booking: null } }];
}

// ── RESET ────────────────────────────────────────────────────────────────────────
if (rawText === '/reset') {
  ['booking_','pending_booking_','photoAsked_','etatAsked_','pendingPhotos_','awaitingConfirmation_','awaitingDevisConfirmation_'].forEach(k => delete staticData[k + chatId]);
  Object.keys(staticData).forEach(k => { if (k.startsWith('verified_' + chatId)) delete staticData[k]; });
  return [{ json: { chatId, output: '✅ Conversation réinitialisée. Comment puis-je vous aider ? 😊', isBookingReady: false, directRecap: false, isCancelRequest: false, booking: null } }];
}

const output = $input.first().json.output;

// ── ÉTAT VÉHICULE — client répond après "pas de photo" ───────────────────────────
if (staticData['etatAsked_' + chatId]) {
  const etatMap = { 'normal': 'normal', 'sale': 'sale', 'très sale': 'tres_sale', 'tres sale': 'tres_sale', 'tres_sale': 'tres_sale' };
  const etat = etatMap[rawText.toLowerCase().trim()];
  if (etat) {
    const booking = staticData['booking_' + chatId];
    if (booking) {
      booking.etat = etat;
      delete staticData['etatAsked_' + chatId];
      return [{ json: { chatId, output: 'Je prépare votre récapitulatif... ⏳', isBookingReady: false, directRecap: true, isCancelRequest: false, booking: null } }];
    }
  }
  return [{ json: { chatId, output: "Merci de choisir l'état de votre véhicule :\n• *Normal* 🟢\n• *Sale* 🟡\n• *Très sale* 🔴", isBookingReady: false, directRecap: false, isCancelRequest: false, booking: null } }];
}

// ── PAS DE PHOTO — demander l'état ───────────────────────────────────────────────
if (staticData['photoAsked_' + chatId] && rawText.match(/pas de photo|sans photo|aucune photo/i)) {
  delete staticData['photoAsked_' + chatId];
  staticData['etatAsked_' + chatId] = true;
  return [{ json: { chatId, output: "Pas de problème ! 😊\n\nQuel est l'état de votre véhicule ?\n• *Normal* 🟢\n• *Sale* 🟡\n• *Très sale* 🔴", isBookingReady: false, directRecap: false, isCancelRequest: false, booking: null } }];
}

// ── DÉTECTION TAG [BOOKING] ───────────────────────────────────────────────────────
const bookingMatch = output.match(/\[BOOKING\]([\s\S]*?)\[\/BOOKING\]/);
let booking = null;

if (bookingMatch) {
  try {
    const rawJson = bookingMatch[1].trim().replace(/nombre_entier/g, '0').replace(/:\s*[a-z_]+_[a-z_]+/gi, ': null');
    booking = JSON.parse(rawJson);
    booking.etat = 'normal';
    const FAKE = ['client','prenom_du_client','prenom nom','prenom','nom','','undefined','null'];
    const phone = (chatId || '').replace('@s.whatsapp.net', '');
    if (!booking.client || FAKE.includes(booking.client.toLowerCase().trim())) {
      booking.client = booking.telephone || phone;
    }
    // Stocker directement + flag photo (la vérif dispo se fait d'abord)
    staticData['booking_' + chatId] = booking;
    staticData['photoAsked_' + chatId] = true;
  } catch (e) { console.error('Erreur JSON Booking: ' + e.message); }
}

const cleanOutput = output.replace(/\[BOOKING\][\s\S]*?\[\/BOOKING\]/, '').trim();

if (booking) {
  // isBookingReady:true → vérif dispo → si ok → demander photos
  return [{ json: { chatId, output: cleanOutput, isBookingReady: true, directRecap: false, isCancelRequest: false, booking } }];
}

return [{ json: { chatId, output: cleanOutput, isBookingReady: false, directRecap: false, isCancelRequest: false, booking: null } }];

const filePath = $json.result.file_path;
const staticData = $getWorkflowStaticData('global');
const token = staticData['telegramBotToken'] || '';
const chatId = $('Lire Token StaticData1').first().json.chatId;
const firstName = $('Lire Token StaticData1').first().json.firstName;

const imageUrl = `https://api.telegram.org/file/bot${token}/${filePath}`;

const prompt = `Tu es un expert en nettoyage automobile professionnel. Analyse l'\u00e9tat de propret\u00e9 de ce v\u00e9hicule selon ces crit\u00e8res STRICTS :

- normal : V\u00e9hicule propre ou tr\u00e8s l\u00e9g\u00e8rement poussi\u00e9reux. Aucune tache visible, aucun d\u00e9p\u00f4t notable. Aspect g\u00e9n\u00e9ral soign\u00e9.
- sale : Poussière accumul\u00e9e, quelques taches ou traces visibles, vitres sal\u00e9es, int\u00e9rieur avec d\u00e9bris l\u00e9gers. N\u00e9cessite un lavage standard.
- tres_sale : Boue \u00e9paisse, salet\u00e9 tr\u00e8s accumul\u00e9e sur plusieurs zones, taches importantes difficiles \u00e0 enlever, v\u00e9hicule manifestement n\u00e9glig\u00e9 depuis longtemps. En cas de doute entre sale et tres_sale, choisis sale.

R\u00e9ponds UNIQUEMENT en JSON valide sans markdown : {"etat":"normal|sale|tres_sale","justification":"description concise en fran\u00e7ais de ce qui justifie ce niveau","confiance":"haute|moyenne|basse"}`;

