    const nextDate = `${next.getUTCFullYear()}-${String(next.getUTCMonth()+1).padStart(2,'0')}-${String(next.getUTCDate()).padStart(2,'0')}`;
    const conflict = bookedSlots.some(bs => {
      if (bs.date !== nextDate) return false;
      const bsStart = bs.startH * 60 + bs.startM;
      const bsEnd = bs.endH * 60 + bs.endM;
      return slotStart < bsEnd && slotEnd > bsStart;
    });
    if (!conflict) {
      alternatives.push(`${dayNames[next.getUTCDay()]} ${String(next.getUTCDate()).padStart(2,'0')} ${monthNames[next.getUTCMonth()]} \u00e0 ${heure}`);
    }
    offset++;
  }
  staticData[verifiedKey] = 'INDISPONIBLE';
  return `INDISPONIBLE. Proposer immédiatement ces alternatives libres : ${alternatives.join(', ')}.`;
} catch(e) {
