const texts = queue.items.sort((a, b) => a.ts - b.ts).map(m => m.text).filter(t => t);
const combined = texts.join('\n').trim();
let patchedJson = { ...initJson };
if (combined) {
  patchedJson = {
    ...initJson,
    body: { ...initJson.body, data: { ...initJson.body.data, message: { ...initJson.body.data.message, conversation: combined } } }
  };
}
return [{ json: { ...patchedJson, _isLatest: true, _msgCount: texts.length } }];
